public class AlphaBlendPainterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String pixel(java.awt.image.BufferedImage img, int x, int y) {
        if (img == null) {
            return "null-image";
        }
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static java.awt.image.BufferedImage render(int width, int height) {
        java.awt.image.BufferedImage img = new java.awt.image.BufferedImage(
                width, height, java.awt.image.BufferedImage.TYPE_INT_RGB);
        java.awt.Graphics2D g = img.createGraphics();
        try {
            AlphaBlendPainter.paint(g, width, height);
        } finally {
            g.dispose();
        }
        return img;
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage a = render(100, 60);
            check("opaque red left of the band (10,30)", "#FF0000", pixel(a, 10, 30));
            check("blue blended over red (35,30)", "#7F0080", pixel(a, 35, 30));
            check("blue blended over white (60,30)", "#7F7FFF", pixel(a, 60, 30));
            check("blend is uniform down the band (35,50)", "#7F0080", pixel(a, 35, 50));
            check("white right of the band (80,30)", "#FFFFFF", pixel(a, 80, 30));
            check("opaque green tab (90,30)", "#00FF00", pixel(a, 90, 30));
            check("white above the green tab (90,10)", "#FFFFFF", pixel(a, 90, 10));
            check("red survives at the bottom-left (10,55)", "#FF0000", pixel(a, 10, 55));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

